import{_ as a,o as l,c as n,am as i}from"./chunks/framework.CiF4W93w.js";const h=JSON.parse('{"title":"简历修改与模拟视频参考学习","description":"","frontmatter":{"title":"简历修改与模拟视频参考学习","excerpt":"摘要","date":"2024-05-13 00:01:01","updated":"2024-05-13 00:01:01"},"headers":[],"relativePath":"Java面试准备/Java 面试准备 2024版本- 简历/面试总结20203/简历修改与模拟视频参考学习.md","filePath":"Java面试准备/Java 面试准备 2024版本- 简历/面试总结20203/简历修改与模拟视频参考学习.md","lastUpdated":null}'),p={name:"Java面试准备/Java 面试准备 2024版本- 简历/面试总结20203/简历修改与模拟视频参考学习.md"};function e(t,s,c,o,r,u){return l(),n("div",null,[...s[0]||(s[0]=[i(`<h3 id="模拟视频学习001" tabindex="-1">模拟视频学习001 <a class="header-anchor" href="#模拟视频学习001" aria-label="Permalink to &quot;模拟视频学习001&quot;">​</a></h3><p>参考： <a href="https://www.bilibili.com/video/BV12a4y1o7m7" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV12a4y1o7m7</a></p><p>物流项目</p><p>自我介绍：物流项目、互联网项目，最近项目内容介绍，技术栈介绍</p><p>介绍项目组负责内容，采用敏捷开发</p><p>优化点：</p><ul><li>面试的时候尽量注意自己的表达语气，平稳输出</li><li>自我介绍的时候尽量表现出自己的优势，从业经验和擅长点，希望未来做什么，之前做过什么项目 <ul><li>1、介绍的时候尽量体现出自己优势点，表现自己技术栈比较匹配，对于自己未来打算表述清晰一点，希望能够通过交流，也感谢这次面试机会，期待和面试官的交流以及后续工作的展开。</li><li>2、高情商一点，注意自己的表达。</li></ul></li></ul><p>对方问题：</p><ul><li><p>1、微服务，怎么处理微服务之间的调用，以及微服务并发</p><ul><li>服务调用 <ul><li>MQ 异步 + OpenFeign 接口同步调用</li><li>参考：微服务调用：OpenFeign 或者 Dubbo 或者 GRpc</li></ul></li><li>服务并发 <ul><li>参考： <ul><li>是这样的面试官，微服务并发的化，这个得看具体的业务需求</li><li>如果是，单纯的查询，简单查询、简单修改的基本操作，如果没有比较复杂的逻辑，那么我们完全可以通过增加机器的方式来实现。</li><li>如果它特别复杂，那可能考虑优化。</li></ul></li><li>建议 <ul><li>一上来不是就各种穿插新的组件来优化，你如果面对并发问题你第一反应应该是解决并发，而不是讨论技术。</li><li>在实际工作公司中，你如果直接使用MQ、Redis各种技术这个需要开发成本的，需要修改源码的！</li><li>MQ解耦复杂逻辑，那也得是非强一致性的业务逻辑</li><li>各种特别泛的问题：你是怎么优化你们项目中的查询、并发、xxx</li><li>比较有经验的面试官，可能会直接问一下你们当时一些并发参数，访问量之类的名词，然后结合实际场景问你的思考和处理方案以及过往经验</li></ul></li><li>所以，我们一定想明白，面试官提的这个场景，合理吗？ <ul><li>合理的话，继续回答</li><li>不合理的话，可以稍微质疑一下！</li></ul></li><li>服务调用 <ul><li>首先，扛不住的话，我们有弹性容，一旦服务调用，上下游服务器调用日志，超出我们预先配置的阈值，包括监控反馈到CPU、IO、内存等资源，频繁占用以及居高不下情况，我们会直接上新的服务器，跑新的容器、服务实例，将这波高峰期扛过去。</li><li>日常的话，不会有这问题，因为我们经过UA用户验收测试、性能测试，都是达到标准的！</li></ul></li><li>并发问题 <ul><li>1、先上服务器扛住并发</li><li>2、结合日志后续优化 <ul><li>如果是业务复杂，考虑使用 MQ 进行系统解耦，异步处理</li><li>如果是查询的话，我们一般会优化索引，优化查询方式，包括使用缓存；</li><li>但是如果是换组件或者添加组件的话，需要进行代码的更新，需要点时间迭代</li></ul></li></ul></li></ul></li></ul></li><li><p>2、微服务组件</p><ul><li>回答不要太千篇一律</li><li>从思想层面，吹一下，从高层上面来说。</li><li>参考 <ul><li>微服务组件的话，在我们公司，主要是基于阿里的微服务落地实现的。</li><li>我们主要考虑的几个问题，服务注册、配置中心、服务监控、服务路由、服务调度，负载均衡、服务治理和服务发现，限流、熔断。我们主要考虑服务技术的契合程度，以及 CP、AP 的选型，我们主要更加倾向于 AP 的选型，当时我们主要是以 Nacos 为主，Nacos 默认是 AP ，同时具备服务注册、配置中心的功能；同时考虑到限流方面的使用，当时我们采用的是 Sentinel 组件，以及服务路由使用 Gateway，使用 Ribbon 进行服务负载均衡，使用 OpenFeign 进行远程调用，同时，考虑到当时场景，还采用了 RocketMQ 消息队列。</li></ul></li><li>小公司的一些面试官，它问不出来一些底层的难得东西，是因为它比较菜，我们完全可以，炸它，炸你不会！</li><li>你要相信，如果是大厂面试官，它一看你简历，从一些简单的问题深入问，问到你不会的地方，就根本不会更加深入的去问了。大厂面试官，一般是专职的，小公司一般是临时的。</li><li>反而一些，啥都不会的，才会各种瞎问。瞎问面试官，直接炸它！（吹）</li></ul></li><li><p>3、插入数据的时候，主键生成规则</p><ul><li>参考 <ul><li>基础维护，比如司机ID，自增ID</li><li>订单：运单ID，雪花算法</li></ul></li><li>稍微问一下：您是问我具体的技术上的 ID 生成吗？ <ul><li>手动指定 ID、主键自增、UUID</li><li>分布式的一些ID生成策略：雪花算法、美团 Leaf</li></ul></li><li>面试官问：数据迁移 雪花算法不合适，咱们该怎么接话 <ul><li>先语气下来解释一下：刚才您问的是 ID 生成，刚刚并没有考虑到数据迁移方面的问题。在这个数据迁移的场景下，考虑 ID策略的话，</li><li>个人感觉呢，这个规则，应该自己定义</li><li>为什么呢？ <ul><li>1、如果规则不是自己定义的话，可能在数据迁移后，很难找到哪些数据是操作某一次迁移的位置、记录</li><li>2、如果是，在项目架构初期，就需要考虑到未来要数据迁移。</li><li>比如说，冷热数据分离，冷数据（3个月）要从主库迁移到从库，可以提前考虑用一些组件、中间件来进行解决，而不是等到问题出现后，再去考虑</li></ul></li></ul></li></ul></li><li><p>4、业务流程讲讲</p><ul><li>调度中心：下单、取件、分配取件、调度中心、算法</li><li>总分</li><li>分主次讲，将核心亮点跟面试管讲。先说步骤，面试官问到的时候，再将细节。</li></ul></li><li><p>1、自我介绍一定要准备好，语气要自信。</p></li><li><p>2、把面试官当普通人，准备好的基础上互相尊重。</p></li><li><p>面试是一个交流的过程，建议：总、分的形式，先说大概的步骤，再说细节。</p></li><li><p>面试管说的每一个问题，都认真回答一下，不要简短回答。</p></li></ul><p>目前问题：如何改简历</p><p>项目背景介绍：看一下公司官网</p><p>离职原因：裁员，主动离职，1 年4 个月，稳定性 → 考虑 → 三年；真实性：吐槽一下。</p><p>第三方接口调用： <a href="https://www.bilibili.com/video/BV1Xg41167om" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1Xg41167om</a></p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240513173830.png" alt="image.png"></p><hr><h3 id="在线简历修改002" tabindex="-1">在线简历修改002 <a class="header-anchor" href="#在线简历修改002" aria-label="Permalink to &quot;在线简历修改002&quot;">​</a></h3><ul><li><p>08：00 - 10：00</p></li><li><p>14：00 - 16：00</p></li><li><p>两个号投，多投，智联，其他招聘软件</p></li><li><p>1、技能一个描述一行</p></li><li><p>2、项目经历：三行左右</p><ul><li>技术点，通过什么技术去解决问题</li></ul></li><li><p>3、Boss 在线简历导出</p></li><li><p>招呼语</p></li><li><p>深圳/广州</p></li><li><p>聊，活跃度，多互动，提升热带</p></li><li><p>在线简历</p></li><li><p>通过率</p></li></ul><hr><ul><li><p>数据拉取</p></li><li><p>Binlog 日志</p></li><li><p>报表：</p></li><li><p><strong>目前找工作是最重要的，先投满，有面试再说，学习放后面。</strong></p></li></ul><hr><p>这里改一下，为对方的模板</p><p>原</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>熟悉 Java  设计模式，如工厂、代理、组合、策略等设计模式，并善用设计原则构建可复用代码；</span></span>
<span class="line"><span>熟悉 volatile、synchronized、Lock、ConcurrentHashMap 、线程池等并发编程技术；</span></span>
<span class="line"><span>熟悉 JVM 内存模型，垃圾回收机制，类加载机制</span></span>
<span class="line"><span>熟悉掌握 Spring、SpringBoot、Spring MVC、MyBatis、Mybatis-Plus、Spring Data JPA 等开源框架;</span></span>
<span class="line"><span>熟练使用 MySQL  关系型数据库；熟悉 RabbitMQ、RocketMQ  等</span></span>
<span class="line"><span>熟悉掌握 Nacos  配置注册中心</span></span></code></pre></div><p>改</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1、本科毕业，学信网可查;</span></span>
<span class="line"><span>2、三年 java  开发经验，拥有微服务架构经验;</span></span>
<span class="line"><span>3、精通 Spring、SpringMVC、SpringBoot、SpringCloud、MyBatis  等开源框架;</span></span>
<span class="line"><span>4、熟练掌握 Mysql、Redis、Oracle  等数据库，熟练使用 Java  常见组件;</span></span>
<span class="line"><span>5、能够和不同的人合作，具备良好的团队协作精神。</span></span></code></pre></div><p>客诉描述（原）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>本平台主要是对司机和货主在交易中产生的投诉进行处理。货主发货，司机接货，中途如果产生纠纷会创建客诉单，该客诉单会流向公司的客服部门，客服进行客诉单的审核，</span></span>
<span class="line"><span>如果涉及退钱的客诉类型还需要客服领导审核。整个模块业务和其他部门交互采用 mq  消息形式，也有采用同步远程调用对方接口的方式。</span></span>
<span class="line"><span>如果有公司垫付费用的情况还会涉及催收单和申诉单的业务产生。客诉系统包括催收单、申请单、客诉单、申诉单。我们部门主要负责整个客诉平台的迭代和优化，提升客服的办事效率。</span></span></code></pre></div><p>改：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>项目概述：本平台专门设计用于集中处理司机与货主间的交易纠纷。它通过创建客诉单，实现从纠纷发生到解决的全流程管理。客诉单由客服部门审核，严重问题需领导复审。该平台采用消息队列和同步接口调用，确保与其他部门的高效交互。在财务方面，涉及垫付时会生成催收和申诉单。我们部门专注于平台的持续迭代，以提高客服处理效率和整体服务质量。</span></span>
<span class="line"><span>技术栈：SpringBoot + MyBatis + SpringCloud + ES + RocketMQ + Redis + MySQL</span></span>
<span class="line"><span>职责</span></span>
<span class="line"><span>1.负责日常的需求开发和技术文档的编写（比如：客诉单创建以及重开，催收单，申请单等需求开发）。</span></span>
<span class="line"><span>2.负责对客诉中台一些响应时间长的接口进行优化，提升接口响应时间；</span></span>
<span class="line"><span>3.编写 redis  分布式锁，解决页面重复提交以及并发修改申请单状态问题。</span></span>
<span class="line"><span>4.负责客诉监控平台日常检测慢 sql  的调优以及针对个别大表制定拆解方案。</span></span>
<span class="line"><span>5.参与讨论客诉核心创单接口涉及分布式事务的处理方案，并采用 rocketMq  半事务消息编写回滚逻辑。</span></span>
<span class="line"><span>6.参与对整个客诉平台的拆分，拆分成客诉平台，催收平台，申请单平台三个独立的微服务，方便职责划分和后期迭代</span></span>
<span class="line"><span>7.独立定位线上 redis  内存溢出问题以及创单接口高峰期频繁出现 full gc  问题</span></span></code></pre></div><p>再改：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1.负责需求分析与开发，包括客诉单的创建与重开、催收单和申请单等关键功能。</span></span>
<span class="line"><span>2.参与客诉平台服务拆分，拆分成客诉平台，催收平台，申请单平台三个独立的微服务，方便职责划分和后期迭代。</span></span>
<span class="line"><span>3.负责客诉监控平台日常检测慢 sql  的调优以及针对个别大表制定拆解方案。</span></span>
<span class="line"><span>4.针对服务调用处理耗时过大的问题，采用并行处理服务调用，调用从10s压缩到2s，考虑到io爆炸的问题，部分接口进行缓存、异步处理。</span></span>
<span class="line"><span>5.针对客诉核心创单接口涉及分布式事务问题，采用 rocketMq 半事务消息编写回滚逻辑。</span></span>
<span class="line"><span>6.针对线上Redis内存溢出问题，排查并优化内存使用策略</span></span>
<span class="line"><span>7.针对创单接口接口高峰期频繁出现TP99耗时变高，分析定位并解决创单接口在高峰期的频繁Full GC问题，提升系统稳定性和性能</span></span></code></pre></div><p>原</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>为了实现集团化汽车工厂管理，提出了多工厂 MES  管理系统，实现数据互通，提高企业生产和管理效率，也能让管理层能够实时监控设备的生产状态，来调整生产业务线、保证管理有序、产品质量、数据可视化。主要覆盖了汽车制造工艺中的计刻、生产、打印、法规模块，集成了统一用户管理中心、智慧大屏、接口统一处理、法规上传。</span></span>
<span class="line"><span>技术栈：Spring、SpringMVC、SpringBoot、MySql、Redis、Mybatis、SpringTask、Vue</span></span></code></pre></div><p>改：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>项目概述：为了实现集团化汽车工厂管理，提出了多工厂 MES  管理系统，实现数据互通，提高企业生产和管理效率，也能让管理层能够实时监控设备的生产状态，来调整生产业务线、保证管理有序、产品质量、数据可视化。主要覆盖了汽车制造工艺中的计划、生产、打印、法规模块</span></span>
<span class="line"><span>技术栈：Spring、SpringCloud、MySql、Redis、Mybatis、Vue</span></span>
<span class="line"><span>职责：</span></span>
<span class="line"><span>1、构建邮件发送模块和企微消息发送模块，解耦消息发送流程；</span></span>
<span class="line"><span>2、针对复杂维度业务，采用设计模式处理复杂业务场景，如模板模式规范了 webservice  接口对接流程；</span></span>
<span class="line"><span>3、针对打印模块业务，采用模板、策略、工厂设计模式，定义装车单打印过程标准和实现对应的多类型打印，使用了 Redis  进行缓存维护数据操作，使用异步 @Async  处理分线打印操作，使用线程池异步记录日志操作；</span></span>
<span class="line"><span>4、优化了计划排产模块的计划导入操作和过点导出操作。</span></span>
<span class="line"><span>5、负责车间报表数据后端获取逻辑的编写。</span></span></code></pre></div><p>工作描述</p><p>原</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1、承担部分功能模块的开发，参与相关技术文档的编写</span></span>
<span class="line"><span>2、参与历史遗留问题的定位与优化</span></span>
<span class="line"><span>3、参与微服务拆分以及接口重构</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>1、根据需求文档，进行功能模块的设计与开发 </span></span>
<span class="line"><span>2、按照公司技术文档规范编写相关的技术文档 </span></span>
<span class="line"><span>3、负责根据客户需求对产品进行二次开发和持续迭代</span></span></code></pre></div><p>拉钩和智联也修改一下</p><p>后面投吧，没准备的话也也是死。</p><hr><h3 id="面试实录视频学习003" tabindex="-1">面试实录视频学习003 <a class="header-anchor" href="#面试实录视频学习003" aria-label="Permalink to &quot;面试实录视频学习003&quot;">​</a></h3><p>参考： <a href="https://www.bilibili.com/video/BV1ot421w7Ug" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1ot421w7Ug</a></p><p>自我介绍、项目介绍</p><ul><li>问题：是否清楚微服务底层原理。</li><li>问题：有没有使用 SPI 解决业务上的问题</li><li>问题：</li></ul><p>SPI 通常指的是 Spring 框架为开发者提供的一套可扩展的接口和抽象类，开发者基于这些标准去实现自己的版本。</p><ul><li>Spring 的 SPI <ul><li>Spring 的核心框架提供了很多接口和抽象类，比如 BeanPostProcessor、PropertySource、ApplicationContextInitialize</li></ul></li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240515095518.png" alt="image.png"></p><p>后续略，整合到章节篇内容，速刷也整合一下到章节篇。</p>`,49)])])}const g=a(p,[["render",e]]);export{h as __pageData,g as default};
